sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if(!api.data.form.form || !api.data.form.form.header)
    return [];
  var labelValuePairs = api.data.form.form.header.transformedSecondaryItems;
  if(!labelValuePairs || !labelValuePairs.length)
    return [];
  labelValuePairs.forEach(pair => {
    if(pair.value.type == 'text-link') {
      pair.value.type = 'string';
      pair.value.value = pair.value.data.displayValue;
    }
  });
	return labelValuePairs;
}
